public static class Solution
{
    public static int[] Rotate(int[] values, int k)
    {
        int n = values.Length;
        var result = new int[n];
        if (n == 0) return result;
        int shift = ((k % n) + n) % n;
        for (int i = 0; i < n; i++) result[(i + shift) % n] = values[i];
        return result;
    }

    public static List<int> MergeSorted(IReadOnlyList<int> a, IReadOnlyList<int> b)
    {
        var result = new List<int>(a.Count + b.Count);
        int i = 0, j = 0;
        while (i < a.Count && j < b.Count) result.Add(a[i] <= b[j] ? a[i++] : b[j++]);
        while (i < a.Count) result.Add(a[i++]);
        while (j < b.Count) result.Add(b[j++]);
        return result;
    }

    public static List<int> RunningTotals(IReadOnlyList<int> values)
    {
        var result = new List<int>(values.Count);
        int total = 0;
        foreach (int v in values)
        {
            total += v;
            result.Add(total);
        }
        return result;
    }

    public static List<string> Compact(IReadOnlyList<string?> items)
    {
        var result = new List<string>();
        foreach (string? item in items)
        {
            if (string.IsNullOrWhiteSpace(item)) continue;
            string t = item.Trim();
            if (!result.Contains(t)) result.Add(t);
        }
        return result;
    }
}

