Test("rotating", () =>
{
    int[] data = [1, 2, 3, 4, 5];
    CheckEq(Rotate(data, 2), new[] { 4, 5, 1, 2, 3 });
    CheckEq(Rotate(data, -1), new[] { 2, 3, 4, 5, 1 });
    CheckEq(Rotate(data, 12), new[] { 4, 5, 1, 2, 3 });
    CheckEq(Rotate(data, 0), data);
    Check(!ReferenceEquals(Rotate(data, 0), data), "return a new array");
    CheckEq(data, new[] { 1, 2, 3, 4, 5 });
    CheckEq(Rotate(new int[0], 3).Length, 0);
});

Test("merging sorted lists", () =>
{
    CheckEq(MergeSorted([1, 4, 9], [2, 3, 10, 11]), new[] { 1, 2, 3, 4, 9, 10, 11 });
    CheckEq(MergeSorted([], [5]), new[] { 5 });
    CheckEq(MergeSorted([2, 2], [2]), new[] { 2, 2, 2 });
});

Test("running totals", () =>
{
    CheckEq(RunningTotals([1, 2, 3]), new[] { 1, 3, 6 });
    CheckEq(RunningTotals([5, -5, 5]), new[] { 5, 0, 5 });
    CheckEq(RunningTotals([]).Count, 0);
});

Test("compacting", () =>
{
    CheckEq(Compact([" a", "a", null, " ", "b"]), new[] { "a", "b" });
    CheckEq(Compact(["x ", "y", " x", "Y"]), new[] { "x", "y", "Y" });
    CheckEq(Compact([null, ""]).Count, 0);
});

